INSERT INTO `v1_2e19eda355d4a8278bfdef9d0b401acb61db7a745af0b0b0aef0da2c1b5fb397` VALUES (1, 1.21875, 1.21875, 11505, 3, "チカのピンバッジ", "ポップでキュートに描かれたチカのピンバッジ。つやつやキラキ\nラのコインのような質感が、コレクター心を刺激するアイテム。");
