INSERT INTO `v1_2e19eda355d4a8278bfdef9d0b401acb61db7a745af0b0b0aef0da2c1b5fb397` VALUES (1, 0.625, 0.75, 11601, 6, "ツムギのボトルキャップ", "ツムギ・オンステージ！ツムギがキャップのステージでかわいく\nポーズを決めている。どこでも好きな場所に気軽に飾ることが可\n能。");
INSERT INTO `v1_2e19eda355d4a8278bfdef9d0b401acb61db7a745af0b0b0aef0da2c1b5fb397` VALUES (1, 0.625, 0.75, 11602, 6, "ツムギのサマーボトルキャップ", "サマー衣装のツムギが、キャップでオンステージ！涼しげな衣装を\nまとい、熱いステージを繰り広げた彼女の勇姿を思い出すことがで\nきる。");
